(25, 170, 2, 2, '2026-02-19 15:53:00', 'conduct', '', 0, '', '', '', '0', 'Verbal Warning', '0', NULL, '2026-02-19 07:53:59', NULL, 'minor', '', 'uploads/pdfs/report_25_20260219_085414.pdf', 1, NULL, '2026-02-19 08:58:00', '\n\n                    <!-- 🔄 AUTO-GENERATED VERSION ─ built from database fields -->\n\n            <div class=\"date-section\">\n                <p>Date: February 19, 2026</p>\n            </div>\n\n            <div class=\"recipient-section\">\n                <p>ZOE GUTIERREZ ADRIANO</p>\n                <p>TECHNICAL SUPPORT REPRESENTATIVE</p>\n                <p>Contact Center - Acer US</p>\n            </div>\n\n            <div class=\"subject-line\">\n                <p><strong>Subject: Formal Incident Report – Conduct and Behavior</strong></p>\n            </div>\n\n            <p>Dear ZOE,</p>\n\n            <div class=\"letter-body\">\n                                    <p>This letter serves as a formal Incident Report regarding a conduct matter on February 19, 2026.<br>\n<br>\nOffense Category: Minor Offense.<br>\nThe following conduct issue has been documented: .<br>\n<br>\n</p>\n\n                    <p>The following details have been recorded regarding this matter:</p>\n\n                    <div class=\"incident-details\">\n                        <p><strong>Date of Incident:</strong> February 19, 2026</p>\n                                                    <p><strong>Offense Category:</strong> <span class=\"offense-badge offense-minor\">Minor Offense</span></p>\n                                                <p><strong>Type of Violation:</strong> </p>\n                                                                                                    <p><strong>Immediate Action Taken:</strong> Verbal Warning</p><p>absent ako bukas</p>\n                                                                    </div>\n\n                    <p>This conduct must be corrected immediately. Continued violations may result in further disciplinary action up to and including termination of employment.</p>\n\n                    <p>You are required to meet with the Human Resources Department within forty-eight (48) hours to discuss this matter and to ensure your understanding of the company\'s conduct expectations.</p>\n\n                \n                <p>Should you wish to discuss this matter, you may coordinate with the Human Resources Department.</p>\n                <p>Thank you for your prompt attention to this matter.</p>\n            </div>\n\n            <div class=\"closing\">\n                <p>Sincerely,</p>\n                <div class=\"signature-line\"></div>\n                <p>Human Resources Department</p>\n            </div>\n\n            <div class=\"acknowledgment-section\">\n                <p><strong>EMPLOYEE ACKNOWLEDGMENT:</strong></p>\n                <p>I acknowledge receipt of this Incident Report.</p>\n                <p><strong>Employee Signature:</strong> <span class=\"signature-line-ack\"></span></p>\n                <p><strong>Date Received:</strong> <span class=\"signature-line-ack\"></span></p>\n            </div>\n\n            ', '2026-02-19 16:58:00'),
